package com.smartlibrary.algorithms.string;import java.util.*;
public final class KMP {private KMP(){} public record Result(List<Integer> positions,long comparisons,int[] lps){} public static Result search(String text,String pattern){if(pattern==null||text==null)throw new IllegalArgumentException("Text and pattern cannot be null");if(pattern.isEmpty())return new Result(java.util.stream.IntStream.rangeClosed(0,text.length()).boxed().toList(),0,new int[0]);int[] lps=buildLps(pattern);List<Integer> out=new ArrayList<>();int i=0,j=0;long c=0;while(i<text.length()){c++;if(text.charAt(i)==pattern.charAt(j)){i++;j++;if(j==pattern.length()){out.add(i-j);j=lps[j-1];}}else if(j>0)j=lps[j-1];else i++;}return new Result(out,c,lps);}public static int[] buildLps(String p){int[] l=new int[p.length()];for(int i=1,len=0;i<p.length();){if(p.charAt(i)==p.charAt(len))l[i++]=++len;else if(len>0)len=l[len-1];else l[i++]=0;}return l;}}
